-- Manager V2 acceptance: only the existing isolated disposable lab.
BEGIN
  IF SYS_CONTEXT('USERENV','SESSION_USER') <> 'FWM_LAB' OR
     SYS_CONTEXT('USERENV','CURRENT_SCHEMA') <> 'FWM_LAB' OR
     SYS_CONTEXT('USERENV','CON_NAME') <> 'FREEPDB1' THEN
    RAISE_APPLICATION_ERROR(-20002, 'Unexpected V2 lab destination');
  END IF;
END;
/
INSERT INTO FWM_ACCEPTANCE_PROBE (ID, MARKER) VALUES (2, 'manager-v2-acceptance');
COMMIT;
